        _add(errors, "/accounts", "required", "accounts is required")
    elif not isinstance(payload["accounts"], list):
        _add(errors, "/accounts", "invalid_type", "accounts must be an array")
    else:
        accounts = payload["accounts"]
        if len(accounts) < 1:
            _add(errors, "/accounts", "too_few_accounts", "accounts must contain at least one entry")
        for index, account in enumerate(accounts):
            base = f"/accounts/{index}"
            if not isinstance(account, dict):
                _add(errors, base, "invalid_type", "account must be an object")
                records.append(None)
                continue

            record: dict[str, Any] = {
                "index": index,
                "base": base,
                "code": None,
                "type": None,
                "normal_balance": None,
                "active": None,
                "parent_code": None,
                "parent_valid": False,
            }
            field_invalid = False

            for key in account:
                if key not in _ACCOUNT_FIELDS:
                    _add(
                        errors,
                        f"{base}/{_escape(key)}",
                        "unknown_field",
                        f"unknown field {key!r}",
                    )

            code = _check_string(errors, account, "code", f"{base}/code")
            if code is None:
                field_invalid = True
            record["code"] = code

            name = _check_string(errors, account, "name", f"{base}/name")
            if name is None:
                field_invalid = True

            acc_type: str | None = None
            if "type" not in account:
                _add(errors, f"{base}/type", "required", "type is required")
                field_invalid = True
            elif not isinstance(account["type"], str):
                _add(errors, f"{base}/type", "invalid_type", "type must be a string")
                field_invalid = True
            elif account["type"] not in _ACCOUNT_TYPES:
                _add(
                    errors,
                    f"{base}/type",
                    "invalid_account_type",
                    "type must be one of asset, liability, equity, revenue, expense",
                )
                field_invalid = True
            else:
                acc_type = account["type"]
            record["type"] = acc_type

            balance: str | None = None
            if "normal_balance" not in account:
                _add(errors, f"{base}/active", "required", "normal_balance is required") if False else _add(
                    errors, f"{base}/normal_balance", "required", "normal_balance is required"
                )
