        # 0=未访问, 1=在当前栈中, 2=已完成解析
        state: dict[int, int] = {}

        def walk(node: dict[str, Any]) -> tuple[bool, list[dict[str, Any]] | None]:
            """返回 (是否无环到达根, 若遇环则环上节点序列)。"""
            idx = node["index"]
            mark = state.get(idx, 0)
            if mark == 1:
                # 找到回到当前节点的环，环从此节点开始。
                return False, [node]
            if mark == 2:
                return True, None
            state[idx] = 1
            parent = node.get("parent")
            if not node["parent_valid"] or parent is None:
                state[idx] = 2
                return True, None
            ok, cycle = walk(parent)
            state[idx] = 2
            if not ok and cycle is not None:
                # 仅收集回到环起点之前的节点；起点本身也属于环。
                if node is cycle[0] and len(cycle) > 1:
                    return False, cycle
                if node is cycle[0]:
                    cycle.append(node)
                    return False, cycle
                if state.get(node["index"]) == 1 or all(n is not cycle[0] for n in cycle):
                    cycle.append(node)
                return False, cycle
            return True, None

        # 用稳定的环收集：迭代每个节点，沿链找到重复栈点。
        for record in valid_records:
            if not record["parent_valid"]:
                continue
            order: list[dict[str, Any]] = []
            positions: dict[int, int] = {}
            node = record
            while node is not None and node["parent_valid"] and node.get("parent") is not None:
                idx = node["index"]
                if idx in positions:
                    cycle_nodes = order[positions[idx]:]
                    for cycle_node in cycle_nodes:
                        _add(
                            errors,
                            f"{cycle_node['base']}/parent_code",
                            "parent_cycle",
                            "parent chain must not contain a cycle",
                        )
                    break
                positions[idx] = len(order)
                order.append(node)
                node = node.get("parent")

        # 关系规则：类型一致、启用子科目不得挂停用父科目、余额方向匹配类型。
        for record in valid_records:
            # normal_balance 与 type 的匹配只依赖本科目字段。
            expected_balance = _TYPE_TO_BALANCE[record["type"]]
            if record["normal_balance"] != expected_balance:
                _add(
                    errors,
                    f"{record['base']}/normal_balance",
                    "normal_balance_mismatch",
                    f"{record['type']} accounts must have normal_balance {expected_balance}",
                )
            if not record["parent_valid"]:
                continue
            parent = record.get("parent")
            parent_path = f"{record['base']}/parent_code"
            if record["type"] != parent["type"]:
                _add(
                    errors,
                    parent_path,
                    "parent_type_mismatch",
                    "child account must have the same type as its parent",
                )
            if record["active"] and not parent["active"]:
                _add(
                    errors,
                    parent_path,
                    "inactive_parent",
                    "active account must not be attached to an inactive parent",
                )

    if errors:
        # 同一位置同一错误码去重（环检测可能从多个入口重复触达环节点）。
        deduped = {(item["path"], item["code"]): item for item in errors}
        ordered = sorted(deduped.values(), key=lambda item: (item["path"], item["code"]))
        return 422, {"valid": False, "errors": ordered}

    assert accounts is not None and chart_id is not None and effective_date is not None
    type_counts = {acc_type: 0 for acc_type in _ACCOUNT_TYPES}
    root_count = 0
    for record in valid_records:
        type_counts[record["type"]] += 1
        if record["parent_code"] is None:
            root_count += 1

    return 200, {
        "valid": True,
        "chart_id": chart_id,
        "effective_date": effective_date,
        "account_count": len(valid_records),
        "root_count": root_count,
        "type_counts": type_counts,
    }

