    """在字段合法的科目间推导唯一性、父子与余额方向关系错误。"""
    by_code: dict[str, dict[str, Any]] = {}
    for record in records:
        code = record["code"]
        if code in by_code:
            _add(
                errors,
                f"{record['base']}/code",
                "duplicate_account_code",
